import pandas as pd
import numpy as np

# Load data
gas_df = pd.read_csv('chunks_csv/moran_local_2021_gas.csv')
adj_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Create adjacency dictionary
adj_dict = {}
for _, row in adj_df.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in adj_dict:
        adj_dict[borough] = []
    adj_dict[borough].append(neighbor)

# Ensure all boroughs are in adj_dict
all_boroughs = gas_df['borough'].unique()
for b in all_boroughs:
    if b not in adj_dict:
        adj_dict[b] = []

# Compute average neighbor Gas_value and local statistic
def compute_local_stats(gas_df, adj_dict):
    boroughs = gas_df['borough'].values
    gas_values = gas_df['Gas_value'].values
    local_stats = []
    for i, b in enumerate(boroughs):
        neighbors = adj_dict[b]
        if not neighbors:
            avg_neighbor = 0
        else:
            neighbor_gas = [gas_df.loc[gas_df['borough'] == n, 'Gas_value'].values[0] for n in neighbors]
            avg_neighbor = np.mean(neighbor_gas)
        local_stat = gas_values[i] - avg_neighbor
        local_stats.append(local_stat)
    gas_df['local_stat'] = local_stats
    return gas_df

gas_df = compute_local_stats(gas_df, adj_dict)

# Perform permutations
num_permutations = 500
permuted_local_stats = {borough: [] for borough in gas_df['borough']}

for _ in range(num_permutations):
    shuffled_gas = np.random.permutation(gas_df['Gas_value'].values)
    temp_series = pd.Series(shuffled_gas, index=gas_df['borough'], name='shuffled_gas')
    for i, b in enumerate(gas_df['borough']):
        neighbors = adj_dict[b]
        if not neighbors:
            avg_neighbor = 0
        else:
            neighbor_gas = [temp_series.loc[n] for n in neighbors]
            avg_neighbor = np.mean(neighbor_gas)
        local_stat = temp_series.loc[b] - avg_neighbor
        permuted_local_stats[b].append(local_stat)

# Compute p-values
p_values = {}
for b in gas_df['borough']:
    original_stat = gas_df.loc[gas_df['borough'] == b, 'local_stat'].values[0]
    permuted_stats = permuted_local_stats[b]
    if original_stat > 0:
        count = sum(1 for s in permuted_stats if s >= original_stat)
    else:
        count = sum(1 for s in permuted_stats if s <= original_stat)
    p_values[b] = count / num_permutations

# Determine thresholds for top 5% and bottom 5%
observed_stats = gas_df['local_stat'].values
hot_threshold = np.percentile(observed_stats, 95)
cold_threshold = np.percentile(observed_stats, 5)

# Identify qualifying boroughs
results = []
for b in gas_df['borough']:
    original_stat = gas_df.loc[gas_df['borough'] == b, 'local_stat'].values[0]
    p = p_values[b]
    if p < 0.05:
        if original_stat > hot_threshold:
            results.append((b, 'HH', original_stat))
        elif original_stat < cold_threshold:
            results.append((b, 'LL', original_stat))

# Output
print(f"data_points_used = {len(gas_df)}")
if results:
    final_answer = []
    for res in results:
        final_answer.append(f"{res[0]} ({res[1]}, statistical method={res[2]:.4f})")
    print(f"FINAL ANSWER: {', '.join(final_answer)}")
else:
    print("FINAL ANSWER: none")
